using NUnit.Framework;
using Seqeron.Mcp.Analysis.Tools;

namespace Seqeron.Mcp.EmbossSequenceFormats.Tests;

// <auto-generated by scripts/docs/gen_emboss_wp61_tools.py: do not edit> B09 WP61 (F280): the MCP tools of the EMBOSS sequence programs; the expected text is what the installed EMBOSS 6.6.0 program writes for the example of the tool document.
[TestFixture]
public class EmbossSequenceProgramToolsTests
{

    [Test]
    public void Revseq_WritesWhatTheInstalledProgramWrites()
    {
        var r = EmbossSequenceFormatsTools.Revseq(">s1 d\nAACCGGTT\n");
        Assert.That(r.Text, Is.EqualTo(">s1 Reversed: d\nAACCGGTT\n"));
    }

    [Test]
    public void Transeq_WritesWhatTheInstalledProgramWrites()
    {
        var r = EmbossSequenceFormatsTools.Transeq(">s1 desc here\nATGAAATTTGGGCCCTAGATGCCCTAAGGGATGAAATAA\n", frame: "1");
        Assert.That(r.Text, Is.EqualTo(">s1_1 desc here\nMKFGP*MP*GMK*\n"));
    }

    [Test]
    public void Extractseq_WritesWhatTheInstalledProgramWrites()
    {
        var r = EmbossSequenceFormatsTools.Extractseq(">s1 d\nACGTACGTACGTACGTACGT\n", regions: "3-5,8-10", separate: true);
        Assert.That(r.Text, Is.EqualTo(">s1_3_5 d\nGTA\n>s1_8_10 d\nTAC\n"));
    }

    [Test]
    public void Cutseq_WritesWhatTheInstalledProgramWrites()
    {
        var r = EmbossSequenceFormatsTools.Cutseq(">s1 d\nACGTACGTACGTACGTACGT\n", @from: 3, @to: 5);
        Assert.That(r.Text, Is.EqualTo(">s1 d\nACCGTACGTACGTACGT\n"));
    }

    [Test]
    public void Degapseq_WritesWhatTheInstalledProgramWrites()
    {
        var r = EmbossSequenceFormatsTools.Degapseq(">s1 d\nAC--GT..AC\n");
        Assert.That(r.Text, Is.EqualTo(">s1 d\nACGTAC\n"));
    }

    [Test]
    public void Trimseq_WritesWhatTheInstalledProgramWrites()
    {
        var r = EmbossSequenceFormatsTools.Trimseq(">s1 d\nNNNNACGTACGTNN\n");
        Assert.That(r.Text, Is.EqualTo(">s1 d\nACGTACGT\n"));
    }

    [Test]
    public void Skipseq_WritesWhatTheInstalledProgramWrites()
    {
        var r = EmbossSequenceFormatsTools.Skipseq(">a\nAC\n>b\nGT\n", skip: 1);
        Assert.That(r.Text, Is.EqualTo(">b\nGT\n"));
    }

    [Test]
    public void Nthseq_WritesWhatTheInstalledProgramWrites()
    {
        var r = EmbossSequenceFormatsTools.Nthseq(">a\nAC\n>b\nGT\n", number: 2);
        Assert.That(r.Text, Is.EqualTo(">b\nGT\n"));
    }

    [Test]
    public void Notseq_WritesWhatTheInstalledProgramWrites()
    {
        var r = EmbossSequenceFormatsTools.Notseq(">a1 x\nAC\n>b2 y\nGT\n", exclude: "a*");
        Assert.That(r.Text, Is.EqualTo(">b2 y\nGT\n"));
    }

    [Test]
    public void Pasteseq_WritesWhatTheInstalledProgramWrites()
    {
        var r = EmbossSequenceFormatsTools.Pasteseq(">a x\nAAAATTTT\n", insertSequence: ">b\nCCCC\n", pos: 4);
        Assert.That(r.Text, Is.EqualTo(">a x\nAAAACCCCTTTT\n"));
    }

    [Test]
    public void Trimest_WritesWhatTheInstalledProgramWrites()
    {
        var r = EmbossSequenceFormatsTools.Trimest(">e1 est\nTTTTTTTTACGTACGTNNACGTAAAAAAAAAAAA\n");
        Assert.That(r.Text, Is.EqualTo(">e1 est [poly-A tail removed]\nTTTTTTTTACGTACGTNNACGT\n"));
    }

    [Test]
    public void Newseq_WritesWhatTheInstalledProgramWrites()
    {
        var r = EmbossSequenceFormatsTools.Newseq(name: "nn", description: "d d", @type: "N", residues: "ACGTRXYZ");
        Assert.That(r.Text, Is.EqualTo(">nn d d\nACGTRXYZ\n"));
    }

    [Test]
    public void Yank_WritesWhatTheInstalledProgramWrites()
    {
        var r = EmbossSequenceFormatsTools.Yank(">s1 d\nACGT\n");
        Assert.That(r.Text, Is.EqualTo("fasta::sequence.dat:s1\n"));
    }

    [Test]
    public void Seqcount_WritesWhatTheInstalledProgramWrites()
    {
        var r = EmbossSequenceFormatsTools.Seqcount(">a\nAC\n>b\nGT\n");
        Assert.That(r.Text, Is.EqualTo("2\n"));
    }

    [Test]
    public void Splitter_WritesWhatTheInstalledProgramWrites()
    {
        var r = EmbossSequenceFormatsTools.Splitter(">s1 d\nACGTACGTACGTACGTACGT\n", size: 8);
        Assert.That(r.Text, Is.EqualTo(">s1_1-8 d\nACGTACGT\n>s1_9-16 d\nACGTACGT\n>s1_17-20 d\nACGT\n"));
    }

    [Test]
    public void Maskseq_WritesWhatTheInstalledProgramWrites()
    {
        var r = EmbossSequenceFormatsTools.Maskseq(">s1 d\nACGTACGTACGTACGTACGT\n", regions: "3-5");
        Assert.That(r.Text, Is.EqualTo(">s1 d\nACNNNCGTACGTACGTACGT\n"));
    }

    [Test]
    public void Maskambignuc_WritesWhatTheInstalledProgramWrites()
    {
        var r = EmbossSequenceFormatsTools.Maskambignuc(">a\nACGTRYKMNBDHV-\n");
        Assert.That(r.Text, Is.EqualTo(">a\nACGTNNNNNNNNN-\n"));
    }

    [Test]
    public void Maskambigprot_WritesWhatTheInstalledProgramWrites()
    {
        var r = EmbossSequenceFormatsTools.Maskambigprot(">a\nACDEFBZXUJO*-\n");
        Assert.That(r.Text, Is.EqualTo(">a\nACDEFXXXXXXX-\n"));
    }

    [Test]
    public void Trimspace_WritesWhatTheInstalledProgramWrites()
    {
        var r = EmbossSequenceFormatsTools.Trimspace("  a \t b   c  \n\n x\ty\n");
        Assert.That(r.Text, Is.EqualTo("a b c\n\nx y\n"));
    }

    [Test]
    public void Nospace_WritesWhatTheInstalledProgramWrites()
    {
        var r = EmbossSequenceFormatsTools.Nospace("  a \t b   c  \n\n x\ty\n");
        Assert.That(r.Text, Is.EqualTo("abc\n\nxy\n"));
    }

    [Test]
    public void Notab_WritesWhatTheInstalledProgramWrites()
    {
        var r = EmbossSequenceFormatsTools.Notab("a\tb\n12345678\tc\n");
        Assert.That(r.Text, Is.EqualTo("a       b\n12345678        c\n"));
    }

    [Test]
    public void Noreturn_WritesWhatTheInstalledProgramWrites()
    {
        var r = EmbossSequenceFormatsTools.Noreturn("a\rb\r\nc\n");
        Assert.That(r.Text, Is.EqualTo("a\nb\nc\n"));
    }

    [Test]
    public void Tools_RefuseAnEmptySequenceAndABadValueWithTheMessagesOfTheLibrary()
    {
        Assert.Throws<ArgumentException>(() => EmbossSequenceFormatsTools.Revseq(""));
        var e = Assert.Throws<ArgumentException>(() => EmbossOpenReadingFramesTools.Getorf(">s1\nACGTACGTACGT\n", table: "7"));
        Assert.That(e!.Message, Does.Contain("Bad menu option '7'"));
        Assert.That(EmbossSequenceFormatsTools.Nthseq(">a\nAC\n", number: 2).Messages, Does.Contain("Error: No such sequence - only 1 sequences were input."));
    }}
